// ThemeStdKeys returns just the keys, in order.
func ThemeStdKeys() []string {
	out := make([]string, 0, len(ThemeStd))
	for _, f := range ThemeStd {
		out = append(out, f.Key)
	}
	return out
}

// ThemeStdLookup finds a key in the table.
func ThemeStdLookup(key string) (ThemeStdField, bool) {
	for _, f := range ThemeStd {
		if f.Key == key {
			return f, true
		}
	}
	return ThemeStdField{}, false
}
